<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio Business OS V14.10 — Revenue Forecasting & Goal Planning */
function tuff_beatz_v1410_goal(){return max(0,(float)get_option('_tb_v1410_monthly_revenue_goal',0));}
function tuff_beatz_v1410_monthly_collected($year=0,$month=0){$year=$year?: (int)current_time('Y');$month=$month?: (int)current_time('n');$total=0.0;$q=new WP_Query(array('post_type'=>'tb_request','post_status'=>'publish','posts_per_page'=>300,'fields'=>'ids'));foreach($q->posts as $id){$payments=function_exists('tuff_beatz_payment_data')?tuff_beatz_payment_data($id):array();foreach($payments as $p){if(($p['status']??'')!=='paid'||empty($p['date']))continue;$ts=strtotime((string)$p['date']);if(!$ts)continue;if((int)wp_date('Y',$ts)===$year&&(int)wp_date('n',$ts)===$month)$total+=(float)($p['amount']??0);}}return round($total,2);}
function tuff_beatz_v1410_forecast(){
 $pipeline=function_exists('tuff_beatz_v14_pipeline_summary')?tuff_beatz_v14_pipeline_summary():array();$business=function_exists('tuff_beatz_v14_project_business_summary')?tuff_beatz_v14_project_business_summary():array();$goal=tuff_beatz_v1410_goal();$collected=tuff_beatz_v1410_monthly_collected();$receivable=max(0,(float)($business['receivable']??0));$weighted=max(0,(float)($pipeline['weighted_value']??0));$day=max(1,(int)current_time('j'));$days=max(1,(int)current_time('t'));$run_rate=$collected/$day;$run_rate_month=$run_rate*$days;$conservative=$collected+($receivable*.50)+($weighted*.25);$expected=$collected+($receivable*.75)+($weighted*.50);$upside=$collected+$receivable+$weighted;$progress=$goal>0?min(999,($collected/$goal)*100):0;$expected_progress=$goal>0?min(999,($expected/$goal)*100):0;$gap=$goal>0?max(0,$goal-$expected):0;$needed_daily=$goal>0?max(0,($goal-$collected)/max(1,$days-$day+1)):0;return array('goal'=>$goal,'month_collected'=>$collected,'receivable'=>$receivable,'weighted_pipeline'=>$weighted,'run_rate_month'=>$run_rate_month,'conservative'=>$conservative,'expected'=>$expected,'upside'=>$upside,'progress'=>$progress,'expected_progress'=>$expected_progress,'gap_to_goal'=>$gap,'needed_daily'=>$needed_daily,'days_elapsed'=>$day,'days_in_month'=>$days,'month_label'=>wp_date('F Y'));}
function tuff_beatz_v1410_save_goal(){if(!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())wp_die('Unauthorized',403);check_admin_referer('tb_v1410_save_goal','tb_v1410_nonce');$goal=max(0,(float)($_POST['monthly_goal']??0));update_option('_tb_v1410_monthly_revenue_goal',$goal,false);wp_safe_redirect(add_query_arg('goal_saved','1',home_url('/business-command/')));exit;}
add_action('admin_post_tb_v1410_save_goal','tuff_beatz_v1410_save_goal');
function tuff_beatz_v1410_business_forecast_panel(){if(!is_page('business-command')||!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())return;$f=tuff_beatz_v1410_forecast();$money=function($n){return function_exists('tuff_beatz_money')?tuff_beatz_money($n):'$'.number_format((float)$n,2);};ob_start();?><section class="tb-v1410-forecast"><div class="tb-v1410-head"><div><small>REVENUE PLANNING • V14.10</small><h3><?php echo esc_html($f['month_label']);?> Forecast</h3><p>Scenario planning based on recorded payments, current receivables and probability-weighted pipeline.</p></div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="tb_v1410_save_goal"><?php wp_nonce_field('tb_v1410_save_goal','tb_v1410_nonce');?><label>MONTHLY REVENUE TARGET<input type="number" name="monthly_goal" min="0" step="100" value="<?php echo esc_attr((string)$f['goal']);?>"></label><button type="submit">Save Target</button></form></div><div class="tb-v1410-grid"><article><small>COLLECTED THIS MONTH</small><strong><?php echo esc_html($money($f['month_collected']));?></strong><span><?php echo $f['goal']>0?esc_html(number_format($f['progress'],1).'% of target'):'Set a monthly target';?></span></article><article><small>RUN-RATE ESTIMATE</small><strong><?php echo esc_html($money($f['run_rate_month']));?></strong><span>Based on <?php echo esc_html((string)$f['days_elapsed']);?> elapsed day(s)</span></article><article><small>EXPECTED CASH-FLOW POTENTIAL</small><strong><?php echo esc_html($money($f['expected']));?></strong><span>75% receivables + 50% weighted pipeline</span></article><article><small>GOAL GAP</small><strong><?php echo esc_html($money($f['gap_to_goal']));?></strong><span><?php echo $f['goal']>0?esc_html($money($f['needed_daily']).' per remaining day'):'No target configured';?></span></article></div><div class="tb-v1410-scenarios"><div><small>CONSERVATIVE</small><strong><?php echo esc_html($money($f['conservative']));?></strong><span>Collected + 50% receivables + 25% weighted pipeline</span></div><div class="is-primary"><small>EXPECTED</small><strong><?php echo esc_html($money($f['expected']));?></strong><span><?php echo $f['goal']>0?esc_html(number_format($f['expected_progress'],1).'% of target potential'):'Set target to track coverage';?></span></div><div><small>UPSIDE</small><strong><?php echo esc_html($money($f['upside']));?></strong><span>Collected + all receivables + weighted pipeline</span></div></div></section><?php $html=ob_get_clean();?><script>document.addEventListener('DOMContentLoaded',function(){var anchor=document.querySelector('.tb-v149-intel')||document.querySelector('.tb-biz-kpis');if(!anchor||document.querySelector('.tb-v1410-forecast'))return;var box=document.createElement('div');box.innerHTML=<?php echo wp_json_encode($html);?>;anchor.insertAdjacentElement('afterend',box.firstElementChild);var eye=document.querySelector('.tb-biz-hero .eyebrow');if(eye)eye.textContent='TUFF BEATZ • STUDIO BUSINESS OS V14.10';});</script><?php }
add_action('wp_footer','tuff_beatz_v1410_business_forecast_panel',10);
