s:flex-start;flex-direction:column}}@media(max-width:620px){.tb-v1410-grid,.tb-v1410-scenarios{grid-template-columns:1fr}.tb-v1410-head form{width:100%}.tb-v1410-head label{flex:1}.tb-v1410-head input{width:100%}}');}
